'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const products=[
{id:'spade',name:'Spade Blend',category:'blend',image:'spade.webp',price:245000,unit:'1 kg',tag:'Bold & intense',symbol:'♠',color:'#ede9df',notes:['Dark chocolate','Roasted nuts','Caramel'],short:'Pekat, penuh, dan tetap terasa dalam susu.',description:'Espresso dengan body tebal, karakter cokelat yang dalam, serta akhir rasa yang panjang. Pilihan untuk Anda yang suka kopi kuat, baik dinikmati langsung maupun dipadukan dengan susu dan es.',pair:'Espresso · Kopi susu · Iced latte',character:'Pekat & kuat'},
{id:'love',name:'Love Blend',category:'blend',image:'love.webp',price:265000,unit:'1 kg',tag:'Smooth & balanced',symbol:'♥',color:'#f0e4dc',notes:['Dark chocolate','Caramel','Fruity sweetness'],short:'Seimbang dan lembut untuk setiap hari.',description:'Perpaduan body, rasa manis, dan karakter yang seimbang. Satu blend yang mudah dinikmati dan fleksibel untuk berbagai menu, dari kopi hitam sampai cappuccino.',pair:'Espresso · Cappuccino · Latte',character:'Seimbang & lembut'},
{id:'club',name:'Club Blend',category:'blend',image:'club.webp',price:275000,unit:'1 kg',tag:'Clean & aromatic',symbol:'♣',color:'#e5e8df',notes:['Dark chocolate','Caramel','Toasted nuts'],short:'Aromatik, ringan dinikmati, bersih di akhir.',description:'Profil aromatik dengan body dan rasa manis yang seimbang. Dirancang agar karakter kopinya tetap terasa saat disajikan sebagai kopi hitam dengan volume air lebih banyak.',pair:'Americano · Long black · Kopi hitam',character:'Bersih & aromatik'},
{id:'diamond',name:'Diamond Espresso',category:'blend',image:'diamond.webp',price:325000,unit:'1 kg',tag:'Sweet & expressive',symbol:'♦',color:'#e6e6e9',notes:['Ripe fruit','Caramel','Milk chocolate'],short:'Manis alami dengan sentuhan buah.',description:'Espresso yang ekspresif, dengan rasa manis alami, nuansa buah, dan tekstur lembut. Untuk Anda yang ingin mengeksplorasi karakter kopi yang lebih berlapis.',pair:'Espresso · Flat white · Americano',character:'Manis & ekspresif'},
{id:'americano',name:'Americano Capsule',category:'capsule',image:'capsule-product.jpg',price:75000,unit:'10 kapsul',tag:'Everyday ritual',symbol:'',color:'#eeebe3',notes:['Full body','Smooth finish'],short:'Kopi favorit, dengan cara yang lebih praktis.',description:'Signature Americano dalam format kapsul Monarchy. Praktis untuk ritual pagi, meja kerja, atau kebutuhan kopi di kamar hotel. Pastikan mesin Anda mendukung format kapsul Monarchy sebelum membeli.',pair:'Mesin kapsul Monarchy yang kompatibel',character:'Praktis & konsisten',photo:true},
{id:'sumatra',name:'Sumatra Capsule',category:'capsule',image:'capsule-sumatra.webp',price:85000,unit:'10 kapsul',tag:'Single origin',symbol:'',color:'#e2e9ea',notes:['Single origin','Sumatra'],short:'Pilihan single origin dalam satu kapsul.',description:'Bagian dari koleksi kapsul single origin Monarchy. Membawa pilihan kopi Sumatra ke rutinitas harian dan pengalaman kopi tamu hotel, dengan penyajian yang praktis.',pair:'Mesin kapsul Monarchy yang kompatibel',character:'Single origin',photo:true},
{id:'capsule-machine',name:'Monarchy Capsule Machine',category:'machine',image:'capsule-machine.webp',price:1850000,unit:'unit',tag:'Brew at home',symbol:'',color:'#ede9e2',notes:['Praktis','Ringkas','Pilihan ukuran sajian'],short:'Sudut kopi favorit Anda, dimulai di sini.',description:'Mesin kapsul Monarchy untuk menikmati kopi dengan lebih praktis di rumah, kantor, atau ruang hospitality. Pilihan ukuran sajian membantu menyesuaikan kopi dengan selera Anda.',pair:'Kapsul Monarchy yang kompatibel',character:'Coffee at a touch',photo:true}
];
const icons={bean:'<path d="M5 19C-2 9 12-3 20 5c7 9-7 23-15 14Z M5 19c11-2 3-12 15-14"/>',cup:'<path d="M4 8h12v6a6 6 0 0 1-12 0V8ZM16 9h2a3 3 0 0 1 0 6h-2M3 22h15M7 2v2M12 2v2"/>',box:'<path d="m3 7 9-5 9 5v11l-9 4-9-4V7Zm0 0 9 5 9-5M12 12v10M7 4l10 6"/>',hand:'<path d="M3 18h4l3 3 10-7c2-2 0-4-2-3l-5 3M3 11h6l4 2c2 1 1 4-1 3l-4-1M3 10v10"/>'};
const svg=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]}</svg>`;
const main=$('#main'),panel=$('#panel');let activeCategory='all',searchTerm='',sortOrder='featured',detailQty=1,sectorIndex=0,lastFocus=null,briefText='',pendingCheckout=null;
let cart=[];try{const saved=JSON.parse(localStorage.getItem('monarchy-demo-cart')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99&&['Biji utuh','Espresso','Filter / V60','French press','Kemasan standar'].includes(x.grind));}catch{}
const getProduct=id=>products.find(p=>p.id===id);
const cartTotal=()=>cart.reduce((n,i)=>n+getProduct(i.id).price*i.qty,0);
function persistCart(){try{localStorage.setItem('monarchy-demo-cart',JSON.stringify(cart))}catch{}updateCount()}
function updateCount(){const n=cart.reduce((n,i)=>n+i.qty,0);$('#cart-count').textContent=n;$('.cart-trigger').setAttribute('aria-label',`Buka keranjang, ${n} produk`)}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function navigate(hash){if(location.hash===hash)route();else location.hash=hash}
function addToCart(id,qty=1,grind){const p=getProduct(id);if(!p||!Number.isInteger(qty)||qty<1||qty>99)throw new Error('Produk atau jumlah tidak valid');grind=grind||(p.category==='blend'?'Biji utuh':'Kemasan standar');const found=cart.find(i=>i.id===id&&i.grind===grind);if(found){if(found.qty+qty>99){toast('Maksimal 99 per varian. Untuk pesanan besar, hubungi tim bisnis.');return false}found.qty+=qty}else cart.push({id,qty,grind});persistCart();toast(`${p.name} ditambahkan ke keranjang`);return true}
function productCard(p){return `<article class="product-card"><a class="product-image ${p.photo?'photo':''}" href="#product/${p.id}" style="background:${p.color}" aria-label="Lihat ${p.name}"><span class="product-tag">${p.tag}</span><img src="assets/${p.image}" alt="${p.name}, kemasan asli Monarchy" loading="lazy" width="650" height="800"><span class="product-mark" aria-hidden="true">${p.symbol}</span></a><div class="product-info"><div class="micro">${p.category==='blend'?'Signature espresso blend':p.category==='capsule'?'Coffee capsule':'Coffee equipment'}</div><h3><a href="#product/${p.id}">${p.name}</a></h3><p>${p.category==='blend'?p.notes.join(' · '):p.short}</p><div class="product-buy"><span class="price">${money(p.price)} <small>/ ${p.unit}</small></span><button class="add-btn" data-add="${p.id}" aria-label="Tambah ${p.name} ke keranjang">+</button></div></div></article>`}
const demoPriceNote='<p class="section-note">Harga, ukuran jual, dan pilihan gilingan di preview ini adalah contoh untuk simulasi belanja. Foto kemasan mengikuti materi asli.</p>';
function trust(){return `<section class="trust container"><span class="eyebrow">Bagian dari perjalanan hospitality Indonesia</span><div class="client-names"><span>Santika<small>Hotels & Resorts</small></span><span>Ascott<small>Hospitality</small></span><span>MERUSAKA<small>Nusa Dua · Bali</small></span><span>GRAND INNA<small>Hotels & Resorts</small></span></div><p class="section-note">Pilihan nama pelanggan yang tercantum dalam company profile Monarchy.</p></section>`}
function guides(){return `<div class="guide-grid"><article class="guide-card"><span class="guide-no">01</span><h3>Kopi seperti apa yang Anda suka?</h3><p>Mulai dari rasa. Temukan blend untuk kopi susu, kopi hitam, atau espresso favorit Anda.</p><a class="text-link" href="#guide/find">Temukan blend Anda</a></article><article class="guide-card"><span class="guide-no">02</span><h3>Biji utuh atau kopi giling?</h3><p>Kenali pilihan yang cocok dengan alat seduh di rumah, supaya tidak salah pilih.</p><a class="text-link" href="#guide/grind">Kenali gilingan kopi</a></article><article class="guide-card"><span class="guide-no">03</span><h3>Sudut kopi, tanpa ribet.</h3><p>Hal yang perlu diperhatikan sebelum memilih kapsul dan mesin kopi pertama.</p><a class="text-link" href="#guide/capsule">Baca panduan kapsul</a></article></div>`}
function home(){return `<section class="hero"><div class="hero-copy reveal"><span class="eyebrow"><i class="dash"></i> MONARCHY COFFEE ROASTER · EST. 2012</span><h1>Good coffee.<br>Great days.<br><em>Your way.</em></h1><p class="subcopy">Dari cangkir pertama di rumah hingga kopi favorit pelanggan Anda. Temukan rasa yang pas, bersama Monarchy.</p><div class="button-row"><a href="#shop" class="btn">Temukan Kopi Anda</a><a href="#business" class="btn outline">Untuk Bisnis</a></div><div class="hero-footnote"><img src="assets/favicon.png" alt=""><span>Diracik dengan perhatian.<br>Dinikmati dengan cara Anda.</span></div></div><div class="hero-media"><img src="assets/brand-story.webp" alt="Kemasan kuning Monarchy Coffee bersama kopi seduh dan biji kopi" fetchpriority="high" width="1024" height="1536"><div class="hero-stamp">GOOD COFFEE<strong>since</strong>2012</div><div class="hero-caption"><span>From our roastery, to your everyday.</span><b>01 / MONARCHY</b></div></div></section><div class="benefits container"><div>${svg('bean')}<span><b>Diracik di roastery kami</b><small>Karakter kopi yang dipilih dengan teliti</small></span></div><div>${svg('cup')}<span><b>Ada rasa untuk setiap hari</b><small>Signature blends & coffee capsules</small></span></div><div>${svg('box')}<span><b>Dari rumah hingga bisnis</b><small>Pilihan kopi untuk beragam kebutuhan</small></span></div><div>${svg('hand')}<span><b>Partner kopi sejak 2012</b><small>Bertumbuh bersama dunia hospitality</small></span></div></div><section class="section container"><div class="section-heading"><div><span class="eyebrow">THE SIGNATURE COLLECTION</span><h2>Empat karakter.<br>Satu kopi favorit Anda.</h2></div><a href="#shop" class="text-link">Jelajahi semua kopi</a></div><div class="products-grid">${products.slice(0,4).map(productCard).join('')}</div>${demoPriceNote}</section><section class="split-feature"><div class="feature-img"><img src="assets/capsule-hero.webp" alt="Kapsul Americano Monarchy dan mesin kopi asli" loading="lazy" width="1600" height="1068"></div><div class="feature-copy"><span class="eyebrow">SMALL CAPSULE. GOOD MOMENT.</span><h2>Ritual kopi Anda,<br>dibuat lebih mudah.</h2><p>Sebelum mulai kerja. Saat jeda sebentar. Kapan pun Anda butuh kopi yang praktis, ada kapsul Monarchy.</p><ul class="feature-list"><li>Signature Americano & pilihan single origin</li><li>Untuk rumah, kantor, dan kamar hotel</li><li>Lengkapi dengan mesin yang kompatibel</li></ul><a href="#shop/capsule" class="btn">Jelajahi Coffee Capsule</a></div></section><section class="section dark"><div class="container business-preview"><div><span class="eyebrow">MONARCHY FOR BUSINESS</span><h2>Anda punya rencana.<br>Kami punya <em>kopinya.</em></h2><p>Buka kafe, lengkapi pengalaman tamu hotel, atau hadirkan coffee corner di tempat olahraga. Mari susun kebutuhan kopi yang sesuai dengan usaha Anda.</p><a href="#business" class="btn yellow" style="margin-top:32px">Kenali Solusi Bisnis</a></div><div class="solution-list"><a href="#business/solutions"><span class="num">01</span><div><h3>Kopi & pasokan rutin</h3><p>Blend yang tepat untuk menu dan pelanggan Anda.</p></div></a><a href="#business/equipment"><span class="num">02</span><div><h3>Mesin & persiapan coffee bar</h3><p>Mulai dari kebutuhan alat, kapasitas, hingga alur kerja.</p></div></a><a href="#business/white-label"><span class="num">03</span><div><h3>Kopi dengan nama Anda</h3><p>Custom blend untuk membangun identitas brand sendiri.</p></div></a></div></div></section>${trust()}<section class="section container"><div class="section-heading"><div><span class="eyebrow">A LITTLE COFFEE KNOW-HOW</span><h2>Kopi enak, dimulai<br>dari pilihan yang pas.</h2></div><a href="#guide" class="text-link">Buka Coffee Guide</a></div>${guides()}</section><section class="cta-band"><div><h2>Mulai dari secangkir yang Anda suka.</h2><p>Temukan karakter kopi yang cocok untuk hari Anda.</p></div><a href="#shop" class="btn">Belanja Kopi</a></section>`}
function shop(){return `<section class="page-head container reveal"><div class="breadcrumb"><a href="#home">Beranda</a> / Belanja kopi</div><span class="eyebrow">YOUR EVERYDAY COFFEE, SORTED.</span><h1>Temukan kopi Anda.</h1><p>Empat signature blend, kapsul yang praktis, dan mesin untuk melengkapi ritual kopi Anda.</p></section><section class="container shop-bottom"><div class="shop-tools"><div class="tabs" aria-label="Kategori produk">${[['all','Semua produk'],['blend','Coffee beans'],['capsule','Capsules'],['machine','Mesin kopi']].map(([v,n])=>`<button data-category="${v}" class="tab ${activeCategory===v?'active':''}" aria-pressed="${activeCategory===v}">${n}</button>`).join('')}</div><label class="sort">Urutkan <select id="sort"><option value="featured">Pilihan Monarchy</option><option value="low">Harga terendah</option><option value="high">Harga tertinggi</option><option value="name">Nama A–Z</option></select></label></div><div class="search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="shop-search" type="search" placeholder="Cari kopi, karakter rasa, atau mesin…" aria-label="Cari produk" value="${esc(searchTerm)}"></div><p id="result-count" class="small muted" aria-live="polite" style="margin:0 0 22px"></p><div id="product-results" class="products-grid"></div>${demoPriceNote}</section><section class="cta-band"><div><h2>Belanja untuk usaha?</h2><p>Diskusikan pasokan rutin, mesin, dan kebutuhan khusus bisnis Anda.</p></div><a href="#business/consult" class="btn">Konsultasi Kebutuhan</a></section>`}
function filterProducts(){let arr=products.filter(p=>(activeCategory==='all'||p.category===activeCategory)&&[p.name,p.short,...p.notes].join(' ').toLowerCase().includes(searchTerm.toLowerCase()));if(sortOrder==='low')arr.sort((a,b)=>a.price-b.price);if(sortOrder==='high')arr.sort((a,b)=>b.price-a.price);if(sortOrder==='name')arr.sort((a,b)=>a.name.localeCompare(b.name));$('#result-count').textContent=`${arr.length} produk${searchTerm?' ditemukan':''}`;$('#product-results').innerHTML=arr.length?arr.map(productCard).join(''):'<div class="empty" style="grid-column:1/-1"><h3>Belum menemukan kopinya?</h3><p>Coba nama lain atau lihat semua produk.</p><button class="btn outline" data-action="reset-search">Tampilkan semua produk</button></div>';$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===activeCategory);b.setAttribute('aria-pressed',b.dataset.category===activeCategory)})}
function detail(id){const p=getProduct(id);if(!p)return notFound();detailQty=1;return `<div class="container page-head"><div class="breadcrumb"><a href="#home">Beranda</a> / <a href="#shop">Belanja kopi</a> / ${p.name}</div></div><section class="container detail reveal"><div class="detail-visual" style="background:${p.color}"><img src="assets/${p.image}" alt="${p.name}, foto kemasan asli Monarchy" width="650" height="900"></div><div class="detail-copy"><span class="eyebrow">${p.category==='blend'?'MONARCHY SIGNATURE BLEND':p.category==='capsule'?'MONARCHY COFFEE CAPSULE':'MONARCHY COFFEE EQUIPMENT'}</span><h1>${p.name}</h1><span class="detail-price">${money(p.price)}</span><span class="small muted"> / ${p.unit}</span><p>${p.description}</p><div class="taste-tags">${p.notes.map(n=>`<span>${n}</span>`).join('')}</div><div class="field"><span class="field-label">${p.category==='machine'?'Unit':'Kemasan'}</span><span>${p.unit} <small class="muted">· Pilihan contoh</small></span></div>${p.category==='blend'?`<div class="field"><label for="grind">Pilihan gilingan</label><select id="grind"><option>Biji utuh</option><option>Espresso</option><option>Filter / V60</option><option>French press</option></select><small>Pilih biji utuh jika Anda punya grinder sendiri.</small></div>`:''}<div class="buy-row"><div class="quantity" aria-label="Jumlah produk"><button data-detail-qty="-1" aria-label="Kurangi jumlah">−</button><span id="detail-qty" aria-live="polite">1</span><button data-detail-qty="1" aria-label="Tambah jumlah">+</button></div><button class="btn" data-detail-add="${p.id}">Tambah ke Keranjang</button></div><div class="demo-note">Preview belanja: harga dan varian contoh, belum merupakan penawaran resmi. Tidak ada transaksi uang sungguhan.</div><details open><summary>Cocok untuk apa?</summary><p>${p.pair}. ${p.category==='blend'?'Karakter: '+p.character+'. Catatan rasa menggambarkan profil kopi, bukan bahan tambahan.':'Konfirmasi spesifikasi dan kompatibilitas sebelum pembelian nyata.'}</p></details><details><summary>${p.category==='machine'?'Spesifikasi & dukungan':'Tips penyimpanan'}</summary><p>${p.category==='machine'?'Model, daya listrik, dimensi, garansi, dan ketersediaan unit perlu dikonfirmasi dengan tim Monarchy. Foto menggunakan materi produk asli.':'Simpan di tempat sejuk dan kering, jauh dari sinar matahari serta sumber bau. Tutup rapat kemasan setelah digunakan. Ikuti tanggal dan petunjuk pada kemasan produk yang Anda terima.'}</p></details><details><summary>Kebutuhan untuk bisnis?</summary><p>Untuk pasokan rutin, volume besar, atau kebutuhan hospitality, tim Monarchy dapat membantu membahas pilihan yang sesuai.</p><a href="#business/consult" class="text-link" style="margin-top:16px">Bicarakan kebutuhan usaha</a></details></div></section><section class="section container"><div class="section-heading"><div><span class="eyebrow">KEEP EXPLORING</span><h2>Kenali rasa lainnya.</h2></div><a href="#shop" class="text-link">Semua produk</a></div><div class="products-grid">${products.filter(x=>x.id!==id).slice(0,4).map(productCard).join('')}</div></section>`}
const sectors=[
{name:'Kafe & restoran',title:'Kopi yang jadi alasan untuk kembali.',text:'Mulai dari coffee bar pertama hingga melengkapi menu restoran. Sesuaikan karakter kopi dan kebutuhan peralatan dengan menu, ruang, dan ritme pelayanan Anda.',image:'brand-story.webp',alt:'Kopi Monarchy untuk coffee bar',items:['Pilihan house blend untuk espresso dan minuman susu','Kebutuhan mesin dan grinder sesuai volume penyajian','Pembahasan konsep coffee bar, alur kerja, dan persiapan pembukaan']},
{name:'Hotel & resort',title:'Pengalaman kopi, di setiap sudut hotel.',text:'Dari sarapan di restoran hingga kopi pertama di kamar tamu. Susun kebutuhan yang saling terhubung untuk setiap titik pelayanan.',image:'capsule-sumatra.webp',alt:'Kapsul Sumatra Monarchy untuk kebutuhan hotel',items:['Roasted coffee untuk restoran, lounge, dan banquet','Kapsul dan mesin untuk kebutuhan in-room','Rencana pengadaan untuk beberapa titik pelayanan']},
{name:'Kantor & coworking',title:'Jeda yang baik untuk ide berikutnya.',text:'Hadirkan sudut kopi yang mudah digunakan oleh tim, tamu, dan komunitas. Pilih format penyajian yang sesuai dengan pengelola ruang Anda.',image:'capsule-hero.webp',alt:'Kopi kapsul dan mesin Monarchy untuk kantor',items:['Kapsul atau biji kopi sesuai fasilitas yang tersedia','Pembahasan mesin praktis untuk area bersama','Perkiraan pemakaian dan kebutuhan pasokan rutin']},
{name:'Olahraga & lifestyle',title:'Tempat berkumpul setelah bergerak.',text:'Coffee corner di padel club, studio kebugaran, atau ruang komunitas bisa menjadi bagian dari pengalaman pengunjung. Mulai dari menu dan operasional yang masuk akal.',image:'white-label.webp',alt:'Penyajian kopi Monarchy untuk ruang komunitas',items:['Pilihan kopi untuk menu ringkas dan mudah disajikan','Pemetaan kebutuhan alat untuk ruang yang tersedia','Opsi signature blend untuk identitas tempat Anda']}
];
function sectorContent(){const s=sectors[sectorIndex];return `<div class="sector-image"><img src="assets/${s.image}" alt="${s.alt}" loading="lazy"></div><div class="fade-content"><span class="eyebrow">SOLUSI UNTUK ${s.name.toUpperCase()}</span><h3>${s.title}</h3><p>${s.text}</p><ul class="check-list">${s.items.map(t=>`<li>${t}</li>`).join('')}</ul><a href="#business/consult" class="text-link">Diskusikan kebutuhan ${s.name.toLowerCase()}</a></div>`}
function business(){return `<section class="business-hero"><div class="hero-copy reveal"><span class="eyebrow">MONARCHY FOR BUSINESS</span><h1>Bisnis Anda.<br>Karakter Anda.<br>Kopi dari kami.</h1><p class="subcopy">Dari ide coffee corner sampai kebutuhan hotel. Satu percakapan untuk memulai solusi kopi yang tepat bagi usaha Anda.</p><div class="button-row"><a class="btn yellow" href="#business/consult">Bicarakan Rencana Anda</a><a class="btn outline" href="#business/solutions">Jelajahi Solusi</a></div><div class="stats"><div><strong>2012</strong><span>Awal perjalanan kami</span></div><div><strong>4</strong><span>Signature espresso blends</span></div><div><strong>1 partner</strong><span>Beragam kebutuhan kopi</span></div></div></div><div class="hero-media"><img src="assets/white-label.webp" alt="Custom blend Monarchy dan sajian kopi untuk bisnis" fetchpriority="high"><div class="hero-caption"><span>Your next chapter, brewed together.</span><b>FOR BUSINESS</b></div></div></section>${trust()}<section class="section container" id="sectors"><div class="section-heading"><div><span class="eyebrow">DI MANA PUN KOPI MENJADI BAGIAN DARI PENGALAMAN</span><h2>Usahanya berbeda.<br>Kebutuhannya juga.</h2></div><p>Kami mulai dengan memahami tempat, pelanggan, dan cara Anda ingin menyajikan kopi.</p></div><div class="sector-tabs" role="tablist" aria-label="Jenis usaha">${sectors.map((s,i)=>`<button role="tab" id="sector-tab-${i}" aria-selected="${i===sectorIndex}" aria-controls="sector-content" data-sector="${i}" class="${i===sectorIndex?'active':''}">${s.name}</button>`).join('')}</div><div class="sector-content" role="tabpanel" id="sector-content" aria-labelledby="sector-tab-${sectorIndex}">${sectorContent()}</div></section><section class="section container" id="solutions" style="border-top:1px solid var(--line)"><div class="section-heading"><div><span class="eyebrow">FROM BEANS TO BUSINESS</span><h2>Satu partner.<br>Banyak hal jadi lebih mudah.</h2></div><p>Pilih kebutuhan Anda. Kita susun cakupannya bersama, tanpa harus mulai dari semuanya sekaligus.</p></div><div class="service-grid"><article class="service-card"><span class="num">01 /</span><h3>Biji kopi & pasokan rutin</h3><p>Signature blend dan pilihan single origin untuk karakter menu Anda. Bahas profil rasa, volume pemakaian, dan jadwal kebutuhan.</p><small>Roasted coffee · Hospitality supply</small></article><article class="service-card" id="equipment"><span class="num">02 /</span><h3>Mesin & peralatan kopi</h3><p>Bahas kebutuhan mesin semi-otomatis, otomatis, atau kapsul. Pilihan pengadaan dan sewa disesuaikan dengan operasional bisnis.</p><small>Model, biaya, dan ketentuan sewa melalui penawaran</small></article><article class="service-card"><span class="num">03 /</span><h3>Kapsul & in-room coffee</h3><p>Solusi kopi praktis untuk kamar hotel, lounge, atau ruang kerja. Mulai dari pilihan kapsul hingga kompatibilitas mesin.</p><small>Americano · Sumatra · Flores · Colombian Decaf</small></article><article class="service-card"><span class="num">04 /</span><h3>Persiapan kafe & coffee corner</h3><p>Punya rencana membangun kafe? Bicarakan konsep, ruang, alat, dan alur penyajian. Kebutuhan desain maupun pembangunan dibahas sebagai lingkup proyek tersendiri.</p><small>Cakupan pekerjaan dan pelaksana dikonfirmasi saat konsultasi</small></article><article class="service-card"><span class="num">05 /</span><h3>Pengembangan menu & tim</h3><p>Diskusikan pilihan menu, kebutuhan resep, serta kesiapan tim yang akan menyajikan kopi. Bentuk pendampingan disepakati sesuai kebutuhan.</p><small>Ketersediaan pelatihan dan pendampingan perlu dikonfirmasi</small></article><article class="service-card"><span class="num">06 /</span><h3>White label & custom blend</h3><p>Kembangkan karakter rasa untuk brand Anda sendiri. Mulai dari preferensi body, rasa manis, sampai tingkat sangrai.</p><small>Minimum order 250 kg per bulan</small></article></div></section><section class="split-feature equipment-feature"><div class="feature-img"><img src="assets/espresso-machine.webp" alt="Mesin espresso komersial pada company profile Monarchy" loading="lazy" style="object-fit:contain;padding:45px;background:#f7f7f4"></div><div class="feature-copy"><span class="eyebrow">THE HEART OF YOUR COFFEE BAR</span><h2>Mesin yang tepat.<br>Alur kerja yang nyaman.</h2><p>Mesin bukan hanya soal tampilan. Mulai dari jumlah cangkir di jam sibuk, menu yang disajikan, sampai ruang dan daya listrik yang tersedia.</p><ul class="feature-list"><li>Semi-otomatis, otomatis, atau mesin kapsul</li><li>Kebutuhan pengadaan atau program sewa</li><li>Spesifikasi dan dukungan sesuai penawaran</li></ul><a href="#business/consult" class="btn">Diskusikan Pilihan Mesin</a></div></section><section class="white-label dark" id="white-label"><img src="assets/white-label.webp" alt="Kemasan Custom Blend asli Monarchy" loading="lazy"><div class="feature-copy"><span class="eyebrow">YOUR BRAND. YOUR SIGNATURE.</span><h2>Kopi dengan<br>nama Anda.<br>Rasa khas Anda.</h2><p>Wujudkan blend yang punya karakter sendiri. Ceritakan profil rasa yang Anda cari, lalu bahas pengembangan kopi untuk brand Anda bersama Monarchy.</p><div class="moq"><strong>250 kg <small style="font-size:1rem">/ bulan</small></strong><span>Minimum order program white label</span></div><a href="#business/consult" class="btn yellow">Bahas Custom Blend</a></div></section><section class="section container"><div class="section-heading"><div><span class="eyebrow">LET'S MAKE IT HAPPEN</span><h2>Dari obrolan pertama,<br>ke rencana yang jelas.</h2></div><p>Alur awal untuk membahas kerja sama. Detail, waktu, dan biaya mengikuti penawaran yang disepakati.</p></div><div class="steps"><article class="step"><span>01</span><h3>Ceritakan kebutuhan</h3><p>Jenis usaha, lokasi, rencana pembukaan, dan perkiraan pemakaian kopi.</p></article><article class="step"><span>02</span><h3>Susun pilihannya</h3><p>Bahas kopi, format penyajian, kapasitas mesin, dan cakupan pendukung.</p></article><article class="step"><span>03</span><h3>Sepakati rencana</h3><p>Tinjau penawaran, jadwal, serta tanggung jawab masing-masing pihak.</p></article><article class="step"><span>04</span><h3>Mulai kerja sama</h3><p>Jalankan pengadaan atau persiapan sesuai cakupan yang telah disetujui.</p></article></div></section><section class="section consult" id="consult"><div class="container consult-grid"><div class="consult-intro"><span class="eyebrow">EVERY GOOD PARTNERSHIP STARTS WITH A CONVERSATION</span><h2>Jadi, apa rencana<br>besar Anda?</h2><p>Tidak perlu punya semua jawabannya sekarang. Ceritakan yang sudah Anda bayangkan, dan mulai dari sana.</p><div class="contact-card"><h3>Lebih nyaman lewat email?</h3><p><a class="text-link" href="mailto:info@monarchycoffee.com">info@monarchycoffee.com</a></p><p class="small">PT Gemilang Artha Makmur Abadi<br>Swadaya City Square Blok II No. 20, Jakarta Barat</p></div></div><form id="consult-form"><div class="form-grid"><div class="field"><label for="lead-name">Nama Anda</label><input id="lead-name" name="name" autocomplete="name" placeholder="Nama lengkap" required maxlength="100"></div><div class="field"><label for="lead-company">Nama usaha / perusahaan</label><input id="lead-company" name="company" autocomplete="organization" placeholder="Nama usaha Anda" required maxlength="120"></div><div class="field"><label for="lead-email">Email</label><input id="lead-email" name="email" autocomplete="email" type="email" placeholder="nama@perusahaan.com" required maxlength="160"></div><div class="field"><label for="lead-phone">Nomor WhatsApp</label><input id="lead-phone" name="phone" type="tel" autocomplete="tel" placeholder="08xxxxxxxxxx" required pattern="[+0-9 ()-]{8,20}" maxlength="20"></div><div class="field"><label for="lead-sector">Jenis usaha</label><select id="lead-sector" name="sector"><option>Kafe & restoran</option><option>Hotel & resort</option><option>Kantor & coworking</option><option>Olahraga & lifestyle</option><option>Brand kopi / distributor</option><option>Lainnya</option></select></div><div class="field"><label for="lead-city">Kota / lokasi usaha</label><input id="lead-city" name="city" placeholder="Contoh: Jakarta Selatan" required maxlength="100"></div><div class="field"><label for="lead-need">Kebutuhan utama</label><select id="lead-need" name="need"><option>Pasokan biji kopi</option><option>Mesin kopi / sewa mesin</option><option>Kapsul & in-room coffee</option><option>Persiapan / pembangunan kafe</option><option>White label / custom blend</option><option>Ingin membahas beberapa kebutuhan</option></select></div><div class="field"><label for="lead-stage">Tahap usaha</label><select id="lead-stage" name="stage"><option>Masih menyusun rencana</option><option>Persiapan pembukaan</option><option>Sudah beroperasi</option><option>Pengembangan cabang</option></select></div><div class="field wide"><label for="lead-message">Ceritakan sedikit rencananya</label><textarea id="lead-message" name="message" placeholder="Misalnya: ingin membuka coffee corner di padel club, sekitar 50 cangkir per hari…" maxlength="2000"></textarea></div></div><label class="consent"><input type="checkbox" required> Saya setuju informasi ini disiapkan sebagai brief untuk tim Monarchy.</label><button type="submit" class="btn full">Siapkan Brief Konsultasi</button><p class="small muted" style="margin-top:12px">Anda bisa meninjau brief, lalu membukanya di email. Tidak ada data yang dikirim otomatis.</p></form></div></section><section class="section container faq-grid"><div><span class="eyebrow">GOOD QUESTIONS</span><h2>Sebelum kita<br>mulai ngobrol.</h2><p>Beberapa hal yang mungkin sedang Anda pikirkan.</p></div><div><details><summary>Apakah harus sudah punya kafe?</summary><p>Tidak. Anda bisa memulai diskusi saat masih menyusun rencana. Ceritakan konsep, lokasi, dan kebutuhan awal supaya pilihan kopi serta peralatannya bisa dibahas sejak awal.</p></details><details><summary>Bisa untuk hotel, kantor, atau tempat olahraga?</summary><p>Bisa diajukan untuk dibahas. Monarchy memiliki pengalaman di hotel, restoran, dan kafe. Untuk kantor, coffee corner tempat olahraga, dan ruang lainnya, kesesuaian solusi akan ditinjau berdasarkan operasional dan kebutuhan Anda.</p></details><details><summary>Apakah Monarchy juga membangun kafe?</summary><p>Kebutuhan persiapan atau pembangunan kafe dapat Anda masukkan dalam brief. Cakupan desain, konstruksi, pelaksana, biaya, serta jadwal harus dikonfirmasi dan disepakati secara terpisah. Layanan konstruksi belum dirinci dalam company profile.</p></details><details><summary>Bagaimana ketentuan sewa mesin?</summary><p>Company profile mencantumkan program sewa mesin. Ketersediaan model, masa sewa, biaya, deposit, perawatan, dan syarat pembelian kopi perlu dikonfirmasi melalui penawaran tim Monarchy.</p></details><details><summary>Berapa minimum pemesanan kopi?</summary><p>Program white label memiliki minimum order 250 kg per bulan. Minimum order roasted coffee, kapsul, atau kerja sama lainnya perlu dikonfirmasi sesuai jenis produk dan skema pengadaan.</p></details><details><summary>Apakah bisa mencoba kopi sebelum kerja sama?</summary><p>Sampaikan kebutuhan pencicipan atau sampel dalam brief konsultasi. Tim Monarchy dapat mengonfirmasi ketersediaan, mekanisme, dan biaya jika ada.</p></details></div></section>`}
function story(){return `<section class="container section story-hero reveal"><div><span class="eyebrow">OUR STORY · SINCE 2012</span><h1>Berawal dari kopi.<br>Bertumbuh bersama<br>orang-orangnya.</h1><p>Pada 2012, perjalanan kami dimulai dari sebuah micro roastery. Fokusnya sederhana: menyediakan kopi untuk hotel, restoran, dan kafe.</p><p>Di bawah PT Gemilang Artha Makmur Abadi, Monarchy berkembang dengan pilihan roasted coffee, kapsul, serta mesin kopi. Karena kopi yang baik bukan hanya soal rasa, tetapi juga bagaimana kopi menjadi bagian dari hari dan usaha seseorang.</p><div class="button-row"><a href="#shop" class="btn">Kenali Kopi Kami</a><a href="#business" class="text-link">Tumbuh bersama Monarchy</a></div></div><img src="assets/brand-story.webp" alt="Kemasan asli Monarchy Coffee dan kopi yang sedang diseduh"></section><section class="section container" style="border-top:1px solid var(--line)"><span class="eyebrow">ONE CUP, ONE CHAPTER AT A TIME</span><h2>Perjalanan yang terus diseduh.</h2><div class="timeline">${[['2012','Awal perjalanan','Memulai micro roastery untuk segmen hotel, kafe, dan restoran.'],['2014','Kapasitas baru','Investasi mesin roasting berkapasitas 15 kg per batch.'],['2019','Wajah Monarchy','Pembaruan brand, identitas visual, dan kemasan produk.'],['2021','Bersama hospitality','Mengembangkan kerja sama pengadaan kopi dengan jaringan hotel.'],['2023','Terus berkembang','Memperluas portofolio melalui pengembangan produk.']].map(([y,t,p])=>`<div><strong>${y}</strong><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section>${trust()}<section class="cta-band"><div><h2>Bab berikutnya, mungkin bersama Anda.</h2><p>Mari bicarakan kopi untuk keseharian atau usaha Anda.</p></div><a href="#business/consult" class="btn">Mulai Percakapan</a></section>`}
function guide(id){if(!id)return `<section class="page-head container"><span class="eyebrow">COFFEE GUIDE</span><h1>Kenali kopi.<br>Nikmati dengan cara Anda.</h1><p>Panduan singkat untuk memilih rasa, gilingan, dan format kopi yang cocok.</p></section><section class="container section" style="padding-top:10px">${guides()}</section><section class="split-feature"><div class="feature-img"><img src="assets/capsule-hero.webp" alt="Kapsul Americano Monarchy" loading="lazy"></div><div class="feature-copy"><span class="eyebrow">START SIMPLE</span><h2>Tidak ada satu cara<br>untuk menikmati kopi.</h2><p>Anda suka kopi susu yang pekat atau Americano yang ringan? Mulai dari selera Anda sendiri, lalu temukan kopi yang paling pas.</p><a href="#shop" class="btn">Jelajahi Koleksi</a></div></section>`;
const content={find:`<span class="eyebrow">COFFEE GUIDE / 01</span><h1>Mulai dari rasa<br>yang Anda suka.</h1><p>Memilih kopi tidak harus rumit. Bayangkan minuman yang paling sering Anda pesan, lalu gunakan karakter rasa sebagai titik awal.</p><h2>Suka kopi susu yang terasa kopinya?</h2><p>Kenali <a class="text-link" href="#product/spade">Spade Blend</a>. Profilnya pekat dengan karakter dark chocolate, roasted nuts, dan caramel. Kopinya dirancang agar tetap hadir saat dipadukan dengan susu atau es.</p><h2>Ingin satu kopi untuk banyak menu?</h2><p><a class="text-link" href="#product/love">Love Blend</a> menawarkan profil yang seimbang dan lembut. Pilihan untuk Anda yang bergantian menikmati espresso, cappuccino, atau latte.</p><h2>Lebih sering minum kopi hitam?</h2><p>Coba kenali <a class="text-link" href="#product/club">Club Blend</a>, dengan profil aromatik yang tetap ekspresif dalam sajian kopi lebih panjang.</p><h2>Suka mengeksplorasi rasa?</h2><p><a class="text-link" href="#product/diamond">Diamond Espresso</a> punya karakter manis alami, sentuhan buah, dan tekstur lembut.</p><p class="demo-note">Tasting notes adalah deskripsi karakter rasa kopi, bukan daftar bahan tambahan. Hasil seduhan juga dipengaruhi air, alat, dan cara menyeduh.</p>`,grind:`<span class="eyebrow">COFFEE GUIDE / 02</span><h1>Biji utuh atau<br>kopi giling?</h1><p>Pilih berdasarkan alat yang Anda gunakan. Jika punya grinder, biji utuh memberi keleluasaan untuk menggiling sesaat sebelum menyeduh.</p><h2>Sesuaikan dengan alat seduh.</h2><table><thead><tr><th>Alat</th><th>Titik awal gilingan</th></tr></thead><tbody><tr><td>Mesin espresso</td><td>Halus</td></tr><tr><td>Filter / V60</td><td>Sedang ke halus</td></tr><tr><td>French press</td><td>Kasar</td></tr></tbody></table><p>Ini panduan awal, bukan angka yang berlaku untuk semua alat. Sesuaikan gilingan dengan resep, waktu seduh, dan hasil rasa. Untuk espresso, grinder dan penyetelan yang tepat sangat berpengaruh.</p><h2>Belum punya grinder?</h2><p>Pastikan ketersediaan layanan giling sebelum memesan. Sebutkan alat seduh Anda supaya pilihan gilingannya bisa disesuaikan.</p><h2>Simpan dengan sederhana.</h2><p>Tutup kemasan dengan rapat, jauhkan dari panas, kelembapan, dan sinar matahari langsung. Ikuti petunjuk penyimpanan dan informasi tanggal pada kemasan.</p>`,capsule:`<span class="eyebrow">COFFEE GUIDE / 03</span><h1>Kopi praktis.<br>Tetap pilih yang pas.</h1><p>Kapsul bisa menjadi pilihan saat Anda ingin kopi dengan persiapan yang ringkas. Tetapi tidak semua kapsul cocok untuk semua mesin.</p><h2>Cek kompatibilitas lebih dulu.</h2><p>Sebelum membeli, cocokkan format kapsul dengan model mesin Anda. Kapsul Monarchy pada materi ini tidak otomatis kompatibel dengan semua sistem kapsul lain. Konfirmasikan model yang digunakan kepada tim Monarchy.</p><h2>Pilih sesuai kebiasaan.</h2><p>Signature Americano adalah salah satu pilihan dalam koleksi Monarchy. Tersedia juga pilihan single origin Sumatra, Flores, dan Colombian Decaf dalam company profile. Ketersediaan aktual perlu dikonfirmasi.</p><h2>Untuk rumah atau bisnis?</h2><p>Di rumah, pertimbangkan ruang dan frekuensi penggunaan. Untuk kantor atau hotel, tambahkan pertimbangan jumlah pengguna, titik pelayanan, dan pengadaan kapsul.</p><a class="btn" href="#shop/capsule">Lihat Coffee Capsules</a>`};return content[id]?`<article class="article reveal"><div class="breadcrumb"><a href="#guide">Coffee Guide</a> / Panduan</div>${content[id]}<div class="button-row"><a href="#guide" class="text-link">Kembali ke Coffee Guide</a></div></article>`:notFound()}
function notFound(){return '<section class="container section empty"><span class="eyebrow">HALAMAN TIDAK DITEMUKAN</span><h1>Kembali ke kopi favorit?</h1><p>Halaman ini tidak tersedia.</p><a href="#shop" class="btn">Jelajahi produk</a></section>'}
function checkout(){if(!cart.length)return '<section class="container section empty"><h1>Keranjang Anda masih kosong.</h1><p>Pilih kopi favorit sebelum melanjutkan.</p><a href="#shop" class="btn">Mulai Belanja</a></section>';return `<section class="page-head container"><div class="breadcrumb"><a href="#shop">Belanja kopi</a> / Checkout</div><h1>Satu langkah lagi<br>ke kopi favorit.</h1><div class="checkout-steps"><span>01 Keranjang</span><span class="active">02 Pengiriman & pembayaran</span><span>03 Ringkasan simulasi</span></div></section><section class="container checkout"><form id="checkout-form"><div class="demo-note">Mode simulasi. Gunakan data contoh. Tidak ada pembayaran nyata, pemesanan, atau pengiriman data ke server.</div><div class="checkout-block"><h2>01. Informasi penerima</h2><div class="form-grid"><div class="field"><label for="buyer-name">Nama lengkap</label><input id="buyer-name" name="name" autocomplete="off" placeholder="Nama penerima" required maxlength="100"></div><div class="field"><label for="buyer-email">Email</label><input id="buyer-email" name="email" type="email" autocomplete="off" placeholder="nama@email.com" required maxlength="160"></div><div class="field wide"><label for="buyer-phone">Nomor telepon</label><input id="buyer-phone" name="phone" type="tel" autocomplete="off" placeholder="08xxxxxxxxxx" pattern="[+0-9 ()-]{8,20}" required maxlength="20"></div></div></div><div class="checkout-block"><h2>02. Alamat pengiriman</h2><div class="form-grid"><div class="field wide"><label for="buyer-address">Alamat lengkap</label><textarea id="buyer-address" name="address" placeholder="Jalan, nomor rumah, kecamatan" required maxlength="500"></textarea></div><div class="field"><label for="buyer-city">Wilayah</label><select id="buyer-city" name="region"><option value="jabodetabek">Jabodetabek</option><option value="java">Pulau Jawa lainnya</option><option value="outside">Luar Pulau Jawa</option></select></div><div class="field"><label for="buyer-postcode">Kode pos</label><input id="buyer-postcode" name="postcode" inputmode="numeric" pattern="[0-9]{5}" placeholder="5 digit kode pos" required maxlength="5"></div><div class="field wide"><label for="shipping">Pengiriman</label><select id="shipping" name="shipping"><option value="regular">Reguler · contoh 2–5 hari kerja</option><option value="express">Ekspres · contoh 1–3 hari kerja</option></select><small>Biaya dan estimasi adalah simulasi, bukan tarif kurir resmi.</small></div></div></div><div class="checkout-block"><h2>03. Pilih metode pembayaran</h2><div class="payment-options"><label class="payment-option"><input type="radio" name="payment" value="QRIS" checked>QRIS<small>Simulasi pembayaran QR</small></label><label class="payment-option"><input type="radio" name="payment" value="Virtual Account">Virtual Account<small>Simulasi transfer bank</small></label><label class="payment-option"><input type="radio" name="payment" value="E-wallet">E-wallet<small>Simulasi dompet digital</small></label></div><p class="small muted" style="margin-top:15px">Gateway belum terhubung. Preview tidak meminta nomor kartu, PIN, atau OTP.</p></div><button type="submit" class="btn full">Tinjau Simulasi Pembayaran</button></form><aside class="order-summary"><h2>Pesanan Anda</h2>${cart.map(i=>{const p=getProduct(i.id);return `<div class="order-mini"><img src="assets/${p.image}" alt="${p.name}"><div><strong>${p.name}</strong><small>${i.qty} × ${p.unit} · ${esc(i.grind)}</small></div><span>${money(p.price*i.qty)}</span></div>`}).join('')}<div class="total-line"><span>Subtotal</span><span>${money(cartTotal())}</span></div><div class="total-line"><span>Ongkir contoh</span><span id="shipping-cost"></span></div><div class="total-line grand"><span>Total simulasi</span><span id="checkout-total"></span></div><p class="small muted">Tidak ada dana yang akan ditagihkan.</p><button data-action="cart" class="text-link" style="margin-top:20px">Ubah keranjang</button></aside></section>`}
function shippingCost(){return ({jabodetabek:18000,java:28000,outside:45000}[$('#buyer-city')?.value]||18000)+($('#shipping')?.value==='express'?15000:0)}
function updateCheckout(){if($('#shipping-cost')){$('#shipping-cost').textContent=money(shippingCost());$('#checkout-total').textContent=money(cartTotal()+shippingCost())}}
function showPanel(html,drawer=false){if(!panel.open)lastFocus=document.activeElement;panel.classList.toggle('drawer',drawer);$('#panel-content').innerHTML=html;if(!panel.open)panel.showModal()}
function panelHead(title){return `<div class="panel-header"><h2 id="panel-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Tutup"><svg viewBox="0 0 24 24"><path d="m6 6 12 12M6 18 18 6"/></svg></button></div>`}
function closePanel(){panel.close();if(lastFocus?.isConnected)lastFocus.focus()}
function renderCart(){showPanel(`${panelHead('Keranjang Anda <span class="muted">('+cart.reduce((n,i)=>n+i.qty,0)+')</span>')}${cart.length?`<div class="cart-items">${cart.map((i,n)=>{const p=getProduct(i.id);return `<div class="cart-item"><img src="assets/${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><small>${p.unit} · ${esc(i.grind)}</small><div><div class="quantity"><button data-cart-change="${n}" data-delta="-1" aria-label="Kurangi ${p.name}" ${i.qty===1?'disabled':''}>−</button><span>${i.qty}</span><button data-cart-change="${n}" data-delta="1" aria-label="Tambah ${p.name}" ${i.qty>=99?'disabled':''}>+</button></div><button class="remove" data-remove="${n}" aria-label="Hapus ${p.name}">Hapus</button></div></div><span class="item-price">${money(p.price*i.qty)}</span></div>`}).join('')}</div><div class="cart-bottom"><div class="total-line"><strong>Subtotal</strong><strong>${money(cartTotal())}</strong></div><p class="small muted" style="margin-bottom:20px">Ongkir contoh dihitung di checkout. Harga pada preview merupakan simulasi.</p><button class="btn full" data-action="checkout">Lanjut ke Checkout</button><button class="text-link" data-action="close" style="display:block;margin:16px auto 0">Lanjut belanja</button></div>`:'<div class="panel-body empty"><h3>Cangkirnya menunggu.</h3><p>Temukan kopi favorit dan masukkan ke keranjang.</p><button class="btn" data-action="start-shopping">Jelajahi Kopi</button></div>'}`,true)}
function route(){const raw=location.hash.slice(1)||'home';const [page,sub]=raw.split('/');if(panel.open)closePanel();$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='product'&&a.dataset.nav==='shop')));if(page==='shop'){activeCategory=['blend','capsule','machine'].includes(sub)?sub:'all';main.innerHTML=shop();$('#sort').value=sortOrder;filterProducts()}else if(page==='home')main.innerHTML=home();else if(page==='product')main.innerHTML=detail(sub);else if(page==='business')main.innerHTML=business();else if(page==='story')main.innerHTML=story();else if(page==='guide')main.innerHTML=guide(sub);else if(page==='checkout'){main.innerHTML=checkout();updateCheckout()}else main.innerHTML=notFound();document.title=({home:'Good coffee. Great days.',shop:'Belanja Kopi',business:'Solusi Kopi untuk Bisnis',story:'Cerita Kami',guide:'Coffee Guide',checkout:'Checkout — Simulasi',product:getProduct(sub)?.name||'Produk'}[page]||'Halaman')+' | Monarchy Coffee';if(page==='business'&&sub){requestAnimationFrame(()=>document.getElementById(sub)?.scrollIntoView({behavior:'smooth'}));if(sub==='white-label'&&$('#lead-need'))$('#lead-need').value='White label / custom blend'}else window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add){addToCart(b.dataset.add);return}if(b.dataset.detailAdd){if(addToCart(b.dataset.detailAdd,detailQty,$('#grind')?.value))renderCart();return}if(b.dataset.detailQty){detailQty=Math.max(1,Math.min(99,detailQty+Number(b.dataset.detailQty)));$('#detail-qty').textContent=detailQty;return}if(b.dataset.category){activeCategory=b.dataset.category;filterProducts();return}if(b.dataset.sector!==undefined){sectorIndex=Number(b.dataset.sector);$$('[data-sector]').forEach((t,i)=>{t.classList.toggle('active',i===sectorIndex);t.setAttribute('aria-selected',i===sectorIndex)});$('#sector-content').innerHTML=sectorContent();$('#sector-content').setAttribute('aria-labelledby',`sector-tab-${sectorIndex}`);if($('#lead-sector'))$('#lead-sector').selectedIndex=sectorIndex;return}if(b.dataset.cartChange!==undefined){const i=cart[Number(b.dataset.cartChange)];if(i)i.qty=Math.max(1,Math.min(99,i.qty+Number(b.dataset.delta)));persistCart();renderCart();return}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);persistCart();renderCart();return}switch(b.dataset.action){case'menu':{const open=$('#navigation').classList.toggle('open');b.setAttribute('aria-expanded',open);break}case'cart':renderCart();break;case'close':closePanel();break;case'checkout':closePanel();navigate('#checkout');break;case'start-shopping':closePanel();navigate('#shop');break;case'search':searchTerm='';navigate('#shop');setTimeout(()=>$('#shop-search')?.focus(),60);break;case'reset-search':activeCategory='all';searchTerm='';$('#shop-search').value='';filterProducts();break;case'demo-info':showPanel(`${panelHead('Tentang preview ini')}<div class="panel-body"><p>Mockup front-end Monarchy Coffee dengan logo dan foto asli dari website serta company profile yang diberikan.</p><p>Harga, ukuran jual, gilingan, ongkir, serta metode pembayaran adalah contoh. Stok dan pesanan tidak terhubung ke sistem toko. Keranjang tersimpan hanya di browser ini.</p><p>Checkout tidak memproses uang. Formulir bisnis menyiapkan brief yang dapat Anda buka di aplikasi email; brief tidak terkirim otomatis.</p><p class="small muted">Layanan persiapan kafe, konstruksi, dan pelatihan perlu konfirmasi cakupan dengan tim Monarchy sebelum menjadi penawaran resmi.</p></div>`);break;case'confirm-simulation':{if(!pendingCheckout)return;const o=pendingCheckout;showPanel(`${panelHead('Simulasi selesai')}<div class="panel-body success"><div class="success-icon">✓</div><h2>Alur belanja selesai dicoba.</h2><p>Total contoh <strong>${money(o.total)}</strong> dengan metode ${esc(o.payment)}.</p><div class="demo-note">Ini bukan bukti pembayaran. Tidak ada dana dipotong dan tidak ada pesanan nyata yang dibuat. Keranjang tetap tersedia.</div><button class="btn" data-action="start-shopping">Kembali ke Koleksi</button></div>`);pendingCheckout=null;break}case'copy-brief':{if(navigator.clipboard?.writeText)navigator.clipboard.writeText(briefText).then(()=>toast('Brief berhasil disalin')).catch(()=>toast('Silakan pilih dan salin teks brief secara manual.'));else toast('Silakan pilih dan salin teks brief secara manual.');break}}});
document.addEventListener('input',e=>{if(e.target.id==='shop-search'){searchTerm=e.target.value;filterProducts()}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sortOrder=e.target.value;filterProducts()}if(['buyer-city','shipping'].includes(e.target.id))updateCheckout()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-sector]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?sectors.length-1:(sectorIndex+(e.key==='ArrowRight'?1:-1)+sectors.length)%sectors.length;const tab=$(`[data-sector="${index}"]`);tab.click();tab.focus()}});
document.addEventListener('submit',e=>{if(e.target.id==='consult-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));briefText=`BRIEF KONSULTASI MONARCHY COFFEE\n\nNama: ${d.name}\nUsaha: ${d.company}\nEmail: ${d.email}\nWhatsApp: ${d.phone}\nJenis usaha: ${d.sector}\nLokasi: ${d.city}\nKebutuhan: ${d.need}\nTahap: ${d.stage}\n\nRencana:\n${d.message||'Akan dibahas saat konsultasi.'}`;showPanel(`${panelHead('Brief Anda siap ditinjau')}<div class="panel-body"><p>Periksa detailnya, lalu buka di aplikasi email untuk mengirim ke tim Monarchy. Belum ada data yang dikirim.</p><div class="brief">${esc(briefText)}</div><div class="button-row"><a class="btn" href="mailto:info@monarchycoffee.com?subject=${encodeURIComponent('Konsultasi kerja sama — '+d.company)}&body=${encodeURIComponent(briefText)}">Buka di Email</a><button class="btn outline" data-action="copy-brief">Salin Brief</button></div></div>`)}if(e.target.id==='checkout-form'){e.preventDefault();if(!cart.length){toast('Keranjang kosong. Tambahkan produk terlebih dahulu.');return}const d=Object.fromEntries(new FormData(e.target));pendingCheckout={total:cartTotal()+shippingCost(),payment:d.payment};showPanel(`${panelHead('Tinjau simulasi pembayaran')}<div class="panel-body"><p>Halo, ${esc(d.name)}. Berikut ringkasan simulasi Anda.</p><div class="total-line"><span>Produk</span><strong>${cart.reduce((n,i)=>n+i.qty,0)} item</strong></div><div class="total-line"><span>Metode</span><strong>${esc(d.payment)}</strong></div><div class="total-line grand"><span>Total contoh</span><strong>${money(pendingCheckout.total)}</strong></div><div class="demo-note">Payment gateway belum terhubung. Tombol di bawah hanya menyelesaikan alur demonstrasi, bukan melakukan pembayaran.</div><button class="btn full" data-action="confirm-simulation">Selesaikan Simulasi</button><button class="text-link" data-action="close" style="margin-top:18px">Kembali ke checkout</button></div>`)}});
panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()}});
panel.addEventListener('close',()=>{if(location.hash==='#checkout'&&$('#checkout-form')){if(!cart.length)main.innerHTML=checkout();else{const temp=document.createElement('div');temp.innerHTML=checkout();$('.order-summary').replaceWith($('.order-summary',temp));updateCheckout()}}if(lastFocus?.isConnected)lastFocus.focus()});
window.addEventListener('hashchange',route);updateCount();route();
// Progressive enhancement: tools use the same catalog and cart actions as the UI.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_coffee_products',description:'Read the Monarchy preview catalog. All prices are illustrative.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>products.map(({id,name,price,unit,category})=>({id,name,price,unit,category,priceStatus:'illustrative'}))})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'add_coffee_to_demo_cart',description:'Add a catalog product to this browser’s local demo cart. Does not place an order.',inputSchema:{type:'object',properties:{productId:{type:'string'},quantity:{type:'integer',minimum:1,maximum:99}},required:['productId','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.productId!=='string'||!Number.isInteger(input.quantity)||input.quantity<1||input.quantity>99||!getProduct(input.productId))throw new Error('Invalid product or quantity');const added=addToCart(input.productId,input.quantity);if(panel.open&&panel.classList.contains('drawer'))renderCart();return {added,count:cart.reduce((n,i)=>n+i.qty,0),subtotal:cartTotal(),mode:'demo'}}})).catch(()=>{})}catch{}}
